const original = await subscriptionOriginalEvidence(tx, [duplicateId, survivingId]);
const modern = !Array.isArray(before) ? merchantSubscriptionUndo.parse(before) : null;
if (modern) {
  const expected = merchantSubscriptionUndo.parse(after);
  if (original.overflow || JSON.stringify(original.evidence) !== JSON.stringify(expected.originalEvidence)) throw new ServiceError("conflict", "Original subscription scope or observed money changed after the merge. Reconcile it before separating ownership.");
} else if (original.overflow || original.evidence.length) throw new ServiceError("conflict", "This historical merge did not record the new original subscription evidence. Restore the pre-upgrade snapshot to separate it safely.");
const ids = (modern?.movedIds ?? (Array.isArray(before) ? before : [])).filter(
  (each): each is string => typeof each === "string",
);
if (ids.length === 0) return;
await tx
  .update(subscriptions)
  .set({ contactId: duplicateId })
  .where(inArray(subscriptions.id, ids));

invoice.body:
const schema = z.array(z.object({ id: z.string().uuid(), contactId: z.string().uuid(), fingerprint: z.string().regex(/^[a-f0-9]{64}$/).optional() }));
const before = schema.parse(beforeState);
const after = schema.parse(afterState);
const current = await selectRows(tx, [duplicateId, survivingId]);
const currentById = new Map(current?.map((row) => [row.id, row]) ?? []);
if (current === null || current.length !== after.length || after.some((row) => currentById.get(row.id)?.contactId !== row.contactId || currentById.get(row.id)?.fingerprint !== row.fingerprint)) {
  throw new ServiceError(
    "conflict",
    `A ${table.replaceAll("_", " ")} record changed after this merge. Leave the merge in place or restore that record first.`,
  );
}
const movedIds = before.filter((row) => row.contactId === duplicateId).map((row) => row.id);
if (movedIds.length === 0) return;
if (table === "invoices") {
  await tx.update(invoices).set({ contactId: duplicateId }).where(inArray(invoices.id, movedIds));
} else if (table === "tax_exemptions") {
  await allowMerchantTaxWrites(tx);
  await tx.update(taxExemptions).set({ contactId: duplicateId }).where(inArray(taxExemptions.id, movedIds));
} else if (table === "payment_provider_customers") {
  await tx.update(paymentProviderCustomers).set({ contactId: duplicateId }).where(inArray(paymentProviderCustomers.id, movedIds));
} else {
  await tx.update(paymentMethods).set({ contactId: duplicateId }).where(inArray(paymentMethods.id, movedIds));
}

